// Package csvstat owns CSV loading, normalization, profiling, frequency aggregation,
// and rendering. It does not read command-line arguments or terminate the process.
package csvstat

import (
	"encoding/csv"
	"fmt"
	"io"
)

// Record is one normalized CSV record.
type Record []string

// Input is the domain representation passed from loading into profiling.
type Input struct {
	Header  Record
	Records []Record
}

// Load reads one RFC 4180 CSV stream and returns its records. It does not access
// the filesystem, so callers control the source and tests can use any io.Reader.
func Load(reader io.Reader) (Input, error) {
	rows, err := csv.NewReader(reader).ReadAll()
	if err != nil {
		return Input{}, fmt.Errorf("read csv: %w", err)
	}
	if len(rows) == 0 {
		return Input{}, fmt.Errorf("read csv: empty input")
	}
	input := Input{Header: Record(rows[0])}
	for _, row := range rows[1:] {
		input.Records = append(input.Records, Record(row))
	}
	return input, nil
}

--- cli ---
// Package cli owns command-line parsing, dispatch, diagnostics, and exit codes.
package cli

import (
	"flag"
	"fmt"
	"io"
)

const (
	// ExitOK indicates a successful command.
	ExitOK = 0
	// ExitOperational indicates an operational failure.
	ExitOperational = 1
	// ExitUsage indicates invalid command-line usage.
	ExitUsage = 2
	// ExitRejected indicates input rejected by the profiler.
	ExitRejected = 3
)

// Run parses args, dispatches the requested command, and returns its process exit code.
func Run(args []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("csvstat", flag.ContinueOnError)
	flags.SetOutput(stderr)
	flags.Usage = func() {
		_, _ = io.WriteString(stderr, usage())
	}
	help := flags.Bool("help", false, "show command usage")
	column := flags.String("column", "", "profile one column by name")
	frequency := flags.String("freq", "", "show the most frequent values for one column")
	top := flags.Int("top", 10, "maximum number of frequent values to show")
	if err := flags.Parse(args); err != nil {
		return ExitUsage
	}
	if *help {
		if _, err := io.WriteString(stdout, usage()); err != nil {
			return ExitOperational
		}
		return ExitOK
	}
	if flags.NArg() != 1 {
		_, _ = io.WriteString(stderr, usage())
		return ExitUsage
	}
	if *top < 0 {
		_, _ = fmt.Fprintln(stderr, "csvstat: --top must not be negative")
		return ExitUsage
	}
	if *column != "" && *frequency != "" {
		_, _ = fmt.Fprintln(stderr, "csvstat: --column and --freq cannot be used together")
		return ExitUsage
	}
	if *frequency == "" && hasFlag(args, "freq") {
		_, _ = fmt.Fprintln(stderr, "csvstat: --freq requires a column name")
		return ExitUsage
	}

	// Profiling dispatch is intentionally kept behind this boundary. The CSV domain
	// package owns loading and analysis; this package owns process-facing concerns.
	_, _ = fmt.Fprintf(stderr, "csvstat: profiling %q is not configured\n", flags.Arg(0))
	return ExitOperational
}

func hasFlag(args []string, name string) bool {
	for _, arg := range args {
		if arg == "--" {
			return false
		}
		if arg == "--"+name || arg == "-"+name || len(arg) > len(name)+3 && arg[:len(name)+3] == "--"+name+"=" {
			return true
		}
	}
	return false
}

func usage() string {
	return "Usage:\n  csvstat [--column <name>] <file>\n  csvstat --freq <name> [--top <n>] <file>\n\nOptions:\n  --column <name>  profile one column by name\n  --freq <name>    show the most frequent values for one column\n  --top <n>        maximum number of frequent values to show (default 10)\n  --help           show this help text\n"
}

