--- tests ---
package csvstat

import (
	"strings"
	"testing"
)

func TestLoadSeparatesHeaderAndRecords(t *testing.T) {
	input, err := Load(strings.NewReader("name,age\nAda,36\n"))
	if err != nil {
		t.Fatalf("Load returned error: %v", err)
	}
	if len(input.Header) != 2 || input.Header[0] != "name" || input.Header[1] != "age" {
		t.Fatalf("header = %#v, want [name age]", input.Header)
	}
	if len(input.Records) != 1 || input.Records[0][0] != "Ada" {
		t.Fatalf("records = %#v, want one Ada record", input.Records)
	}
}

func TestLoadRejectsEmptyInput(t *testing.T) {
	_, err := Load(strings.NewReader(""))
	if err == nil {
		t.Fatal("Load(empty) returned nil error")
	}
}
package cli

import (
	"bytes"
	"testing"
)

func TestRunRejectsMissingInput(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run(nil, &stdout, &stderr)

	if code != ExitUsage {
		t.Fatalf("Run(nil) = %d, want %d", code, ExitUsage)
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout length = %d, want 0", stdout.Len())
	}
}

func TestRunPrintsHelp(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run([]string{"--help"}, &stdout, &stderr)

	if code != ExitOK {
		t.Fatalf("Run(-help) = %d, want %d", code, ExitOK)
	}
	if stdout.Len() == 0 {
		t.Fatal("help output is empty")
	}
}

func TestRunAcceptsColumnProfileInvocation(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run([]string{"--column", "age", "employees.csv"}, &stdout, &stderr)

	if code != ExitOperational {
		t.Fatalf("profile invocation = %d, want operational dispatch %d", code, ExitOperational)
	}
}

func TestRunAcceptsFrequencyInvocationAndTop(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run([]string{"--freq", "department", "--top", "3", "employees.csv"}, &stdout, &stderr)

	if code != ExitOperational {
		t.Fatalf("frequency invocation = %d, want operational dispatch %d", code, ExitOperational)
	}
}

func TestRunRejectsConflictingModes(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run([]string{"--column", "age", "--freq", "department", "employees.csv"}, &stdout, &stderr)

	if code != ExitUsage {
		t.Fatalf("conflicting modes = %d, want %d", code, ExitUsage)
	}
}

func TestRunRejectsNegativeTop(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run([]string{"--freq", "department", "--top", "-1", "employees.csv"}, &stdout, &stderr)

	if code != ExitUsage {
		t.Fatalf("negative top = %d, want %d", code, ExitUsage)
	}
}

